layers.vertex:
attribute vec3 aO; attribute vec2 aN; attribute float aT; uniform float uTime; varying vec2 vUV; varying float vU;
    void main(){ float u = uTime - aT; if (u < 0. || u > 5.600){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u;
      vec2 uv = vec2(position.x*2.1, mix(-.01, 1., position.y + .5)); vUV = uv;
      vec3 N = vec3(aN.x, 0., aN.y), R = vec3(-aN.y, 0., aN.x);
      float th = uv.x*1.200; vec3 rad = N*cos(th) + R*sin(th);
      float r = 3.200 - 1.400*uv.y*uv.y;                                     /* rises from the ground and curls in over the Mystic */
      r += .06*sin(uv.x*5. - uTime*1.2 + uv.y*3.)*uv.y;                               /* the veil breathes slowly */
      vec3 W = aO + rad*r + vec3(0., uv.y*3.200*(1. - .12*uv.y*uv.y), 0.);
      gl_Position = projectionMatrix*viewMatrix*vec4(W, 1.); }

layers.fragment:
uniform float uTime; uniform vec3 uB, uC, uP; varying vec2 vUV; varying float vU; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); } 
    float topOf(float u){ return pow(max(1. - u*u, 0.), .45); }
    float line(float d, float w){ return exp(-d*d/(w*w)); }
    float h(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5); }
    float vn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3. - 2.*f);
      return mix(mix(h(i), h(i + vec2(1., 0.)), f.x), mix(h(i + vec2(0., 1.)), h(i + vec2(1., 1.)), f.x), f.y); }
    void main(){
      float u = vUV.x, v = vUV.y, SX = 3.840, SY = 3.200, t = uTime;
      float op = eox(clamp(vU/0.600, 0., 1.));                                   /* the wall rises from the ground */
      float tp = topOf(u)*op, e = .004;
      float sl = (topOf(u + e) - topOf(u - e))/(2.*e)*op;
      float dist = (tp - v)*SY/length(vec2(1., sl*SY/SX));                            /* metres to the top edge, constant line width */
      float thin = pow(max(1. - u*u, 0.), .5);
      float db = (v - .015)*SY;                                                        /* bottom border, just above the ground */
      vec2 q = max(vec2(.3) - vec2(dist, db), 0.);
      float d = .3 - length(q);                                                        /* one outline: top + bottom joined by ROUND corners (r 0.3 m) at the ground */
      float lw = .007 + .016*(.35 + .65*thin);
      float edge = line(d, lw)*(.55 + .45*thin);
      float halo = line(d, .12)*.09*step(0., d)*(.4 + .6*thin);
      float inside = smoothstep(-.01, .04, d);
      /* stardust fill: fine twinkling points, denser towards the top edge */
      vec2 g = vec2(u*SX, v*SY)*16.; vec2 gi = floor(g), gf = fract(g) - .5; float hs = h(gi);
      vec2 o = (vec2(h(gi + 3.1), h(gi + 7.7)) - .5)*.6;
      float k = clamp(v/max(tp, .01), 0., 1.);
      float dens = mix(.1, .42, pow(k, 1.5))*(.6 + .8*vn(vec2(u*SX, v*SY)*1.3 + vec2(0., -t*.2)));
      float dust = step(1. - dens, hs)*exp(-dot(gf - o, gf - o)*45.)*(.55 + .45*sin(t*3. + hs*70.));
      float ground = .6 + .4*smoothstep(0., .25, v);
      float fin = smoothstep(5.500, 5.000, vU + .5*vn(vec2(u*SX, v*SY)*2.5 + 5.));   /* dissolve: soft erosion */
      float lum = (edge*.9 + halo + dust*.55*inside*ground)*fin;
      vec3 c = uC*lum + uP*(edge*.32 + dust*inside*.18)*fin;
      float al = inside*.025*ground*fin;
      if (!(max(c.r, max(c.g, max(c.b, al))) >= .002)) discard; gl_FragColor = vec4(c, al); }
